from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/upload")
async def upload(form_data: str = Form(...), file_data: bytes = File(...)):
    return {"form_data": form_data, "file_data": file_data}

client = TestClient(app)

def test_form_before_file():
    # This should work, but according to the bug report, it might fail with 422
    response = client.post(
        "/upload",
        data={"form_data": "hello"},
        files={"file_data": b"world"}
    )
    print(f"Status code: {response.status_code}")
    print(f"Response body: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "file_data": b"world"}

if __name__ == "__main__":
    try:
        test_form_before_file()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

